\documentclass{article}
\usepackage{pgfplots}
\usepackage{amsmath}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty}

\begin{tikzpicture}

\begin{axis}[
trig format plots=rad,
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={draw=none},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
%grid = both,
xmin = -2,
xmax = 2,
ymin = -2.5,
ymax = 2.5,
xtick = {-10,-9,...,10},
ytick = {-10,-9,...,10},
xticklabels = {,,},
yticklabels = {,,},
%minor xtick={-10,-9,...,10},
%minor ytick={-10,-9,...,10},   
xlabel = $x$,
ylabel = {$y$},
xlabel style={below right},
ylabel style={above right},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]

\def\rotang{135}
\def\scale{3.4}
\def\vang{10}
\def\sumang{\vang+\rotang}
\def\halfvang{\sumang/2}
\def\vnorm{0.85}

% v
\draw[blue,line width=1.2pt,arrows={-latex}] (axis cs: 0,0) -- (axis cs: {\vnorm*cos(\vang)},{\vnorm*sin(\vang)})
	node[yshift=0pt, xshift=5pt]{$\mathbf{v}$};

\draw[deepskyblue, line width=0.8pt,{-latex}] (axis cs: {\vnorm*cos(\vang)},{\vnorm*sin(\vang)}) 
		arc[start angle=\vang, end angle={\vang+\rotang}, radius={transformdirectionx(\vnorm)}];

\node[above, deepskyblue] at (axis cs: {1.1*\vnorm*cos(\halfvang)},{1.1*\vnorm*sin(\halfvang)}) {$\dfrac{3\pi}{4}$};

% brace	
\draw[decorate, decoration={brace, amplitude=3pt, raise=3pt}, yshift=0pt] 
	(axis cs:  0,0) -- (axis cs: {\scale*\vnorm*cos(\sumang)},{\scale*\vnorm*sin(\sumang)})
	node [black, midway, yshift=-10pt, xshift=-12pt] {\small $4 |\mathbf{v}|$};

% Av
\draw[red,line width=1.1pt,arrows={-latex}] 
	(axis cs: 0,0) -- (axis cs: {\scale*\vnorm*cos(\sumang)},{\scale*\vnorm*sin(\sumang)})
	node[yshift=5pt,xshift=-8pt]{$A\mathbf{v}$};

\end{axis}

\end{tikzpicture}
\end{document}

